quickstart.claude:
const Anthropic = require('@anthropic-ai/sdk');
const pkg = require('./agent-package.json');
const client = new Anthropic();

const tools = pkg.tools.map(t => ({ name: t.name, description: t.description, input_schema: t.input_schema }));

async function chat(userMessage) {
  const response = await client.messages.create({
    model: 'claude-sonnet-4-20250514',
    max_tokens: 4096,
    system: pkg.system_prompt,
    tools,
    messages: [{ role: 'user', content: userMessage }],
  });

  for (const block of response.content) {
    if (block.type === 'tool_use') {
      const tool = pkg.tools.find(t => t.name === block.name);
      const url = `${PCC_BASE_URL}${tool.endpoint.path}`;
      const result = await fetch(url, {
        method: tool.endpoint.method,
        headers: { 'Content-Type': 'application/json' },
        body: tool.endpoint.method === 'POST' ? JSON.stringify(block.input) : undefined,
      }).then(r => r.json());
      // Feed result back as tool_result...
    }
  }
}

